{
  "name": "Specim短波红外相机",
  "name_en": "Specim SWIR Camera",
  "manufacturer": "Specim",
  "description": "一种短波红外成像相机，用于采集样品在SWIR波段的图像数据，常见于材料识别、分选、农业检测以及科研成像实验。",
  "description_en": "A short-wave infrared imaging camera used to acquire sample images in the SWIR range, commonly used for material identification, sorting, agricultural inspection, and research imaging experiments.",
  "tag_hints": [
    "SWIR imaging",
    "short-wave infrared camera",
    "hyperspectral imaging",
    "spectral analysis",
    "machine vision",
    "serial camera control"
  ],
  "actions": [
    {
      "action_name": "auto-flush",
      "description": "清空相机通信缓冲区。",
      "description_en": "Flush the camera communication buffer."
    },
    {
      "action_name": "auto-message_read",
      "description": "从相机读取一条通信消息。",
      "description_en": "Read a communication message from the camera."
    },
    {
      "action_name": "auto-message_write",
      "description": "向相机写入一条通信消息。",
      "description_en": "Write a communication message to the camera."
    },
    {
      "action_name": "auto-fileno",
      "description": "获取相机通信通道的文件描述符。",
      "description_en": "Get the file descriptor of the camera communication channel."
    }
  ]
}

